// Get the JSON from previous node
const data = $json;

// Parse system info
const system = data.system || {};
const highCpuProcesses = data.high_cpu_processes || [];
const services = data.services || {};
const cronJobs = data.cron_jobs || {};
const backupExists = data.backup_exists;
const logs = data.logs || [];

// Prepare alert messages
let alerts = [];

// Check CPU usage
if (system.cpu_percent > 80) {
    alerts.push(`⚠️ High CPU usage detected: ${system.cpu_percent}%`);
}

// Check RAM usage
const ramUsedPercent = (system.ram_used / system.ram_total) * 100;
if (ramUsedPercent > 85) {
    alerts.push(`⚠️ High RAM usage detected: ${ramUsedPercent.toFixed(1)}%`);
}

// Check backup
if (!backupExists) {
    alerts.push("⚠️ Backup is missing!");
}

// Check services
for (const [service, running] of Object.entries(services)) {
    if (!running) {
        alerts.push(`⚠️ Service ${service} is down!`);
    }
}

// Check for failed cron jobs
for (const [job, success] of Object.entries(cronJobs)) {
    if (!success) {
        alerts.push(`⚠️ Cron job failed: ${job}`);
    }
}

// Check for cert-manager CrashLoopBackOff in logs
const certManagerErrors = logs.filter(line => 
    line.includes("cert-manager-cainjector") && line.includes("CrashLoopBackOff")
);
if (certManagerErrors.length > 0) {
    alerts.push(`⚠️ cert-manager-cainjector is in CrashLoopBackOff!`);
}

// Send to Slack if there are alerts
if (alerts.length > 0) {
    return [{
        json: {
            text: `*Server Alerts:*\n${alerts.join("\n")}`
        }
    }];
} else {
    return [{
        json: {
            text: "✅ All systems operational."
        }
    }];
}
